  1	// Mandatory guardrails for prod stacks (framework layer 5; they compensate OD8, where the stack's
  2	// owners, not the L3 owner team, approve IAM and stateful changes inside domain files).
  3	// Phase 2. Run by `pulumi up --policy-pack` in deploy-prod.yml; "a violation of a mandatory
  4	// policy stops the deployment" (R4.2.2). Exported separately from index.ts so that tests can
  5	// call the checks without the Pulumi engine.
  6	//
  7	// Limits (examples/README.md, E10):
  8	// - A value that is unknown during preview (e.g. a policy document built with
  9	//   pulumi.jsonStringify from a resource created in the same update) makes @pulumi/policy 1.21.0
 10	//   report the check as advisory during preview (✅ server.js). The update should then stop at
 11	//   that resource once the value is known (⚠️ not run here), after earlier resources in the same
 12	//   update may already exist. Access Analyzer (layer 5) is the preview-time check for IAM.
 13	// - Only resources declared in the stack are checked: a customer-managed policy created outside
 14	//   Pulumi and attached here by ARN is checked by name only (admin-equivalent AWS policies).
 15	import * as aws from "@pulumi/aws";
 16	import { ReportViolation, ResourceValidationPolicy, validateResourceOfType } from "@pulumi/policy";
 17	
 18	type Statement = { Effect?: string; Action?: string | string[]; NotAction?: string | string[] };
 19	
 20	function statementsOf(policy: unknown): Statement[] {
 21	    if (policy === undefined || policy === null) return [];
 22	    const doc = typeof policy === "string" ? JSON.parse(policy) : policy;
 23	    const st = (doc as { Statement?: Statement | Statement[] }).Statement ?? [];
 24	    return Array.isArray(st) ? st : [st];
 25	}
 26	
 27	// Services where any wildcard in the action name grants privilege escalation or identity changes,
 28	// e.g. iam:Pass*, iam:*Role*, sts:Assume*.
 29	const NO_WILDCARD_SERVICES = /^(iam|sts|organizations|sso|identitystore):/i;
 30	
 31	function wildcardActions(policy: unknown): string[] {
 32	    const found: string[] = [];
 33	    for (const st of statementsOf(policy)) {
 34	        if (st.Effect !== "Allow") continue;
 35	        if (st.NotAction !== undefined) found.push("NotAction");
 36	        const actions = st.Action === undefined ? [] : Array.isArray(st.Action) ? st.Action : [st.Action];
 37	        for (const a of actions) {
 38	            if (a === "*" || /^[a-z0-9-]+:\*$/i.test(a)) found.push(a);
 39	            else if (NO_WILDCARD_SERVICES.test(a) && a.includes("*")) found.push(a);
 40	        }
 41	    }
 42	    return found;
 43	}
 44	
 45	function report(actions: string[], reportViolation: ReportViolation) {
 46	    if (actions.length > 0) {
 47	        reportViolation(`IAM Allow with a wildcard action (${actions.join(", ")}); name the actions.`);
 48	    }
 49	}
 50	
 51	// AWS managed policies that grant `*` or `<service>:*`: the same grants iam-no-wildcard-actions
 52	// refuses in an inline or customer-managed document. Matched on any partition and path.
 53	function adminEquivalent(arn: unknown): boolean {
 54	    if (typeof arn !== "string") return false;
 55	    const m = /^arn:aws[a-z-]*:iam::aws:policy\/(?:.*\/)?([^/]+)$/.exec(arn);
 56	    return m !== null && (["AdministratorAccess", "PowerUserAccess"].includes(m[1]) || m[1].endsWith("FullAccess"));
 57	}
 58	
 59	function reportArns(arns: unknown, reportViolation: ReportViolation) {
 60	    const bad = ([] as unknown[]).concat(arns ?? []).filter(adminEquivalent);
 61	    if (bad.length > 0) {
 62	        reportViolation(`Attaches an admin-equivalent AWS managed policy (${bad.join(", ")}); write a scoped policy.`);
 63	    }
 64	}
 65	
 66	export const policies: ResourceValidationPolicy[] = [
 67	    {
 68	        name: "iam-no-wildcard-actions",
 69	        description: "IAM policies may not allow `*`, `<service>:*`, wildcards in iam/sts/organizations/sso " +
 70	            "actions, or use NotAction with Allow.",
 71	        enforcementLevel: "mandatory",
 72	        validateResource: [
 73	            validateResourceOfType(aws.iam.Policy, (p, _args, v) => report(wildcardActions(p.policy), v)),
 74	            validateResourceOfType(aws.iam.RolePolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
 75	            validateResourceOfType(aws.iam.UserPolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
 76	            validateResourceOfType(aws.iam.GroupPolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
 77	            validateResourceOfType(aws.iam.Role, (r, _args, v) => {
 78	                for (const inline of r.inlinePolicies ?? []) report(wildcardActions(inline.policy), v);
 79	            }),
 80	        ],
 81	    },
 82	    {
 83	        name: "iam-no-admin-managed-policies",
 84	        description: "No attachment of AdministratorAccess, PowerUserAccess or any AWS managed *FullAccess policy.",
 85	        enforcementLevel: "mandatory",
 86	        validateResource: [
 87	            validateResourceOfType(aws.iam.RolePolicyAttachment, (a, _args, v) => reportArns(a.policyArn, v)),
 88	            validateResourceOfType(aws.iam.UserPolicyAttachment, (a, _args, v) => reportArns(a.policyArn, v)),
 89	            validateResourceOfType(aws.iam.GroupPolicyAttachment, (a, _args, v) => reportArns(a.policyArn, v)),
 90	            validateResourceOfType(aws.iam.PolicyAttachment, (a, _args, v) => reportArns(a.policyArn, v)),
 91	            validateResourceOfType(aws.iam.RolePolicyAttachmentsExclusive, (a, _args, v) => reportArns(a.policyArns, v)),
 92	            validateResourceOfType(aws.iam.UserPolicyAttachmentsExclusive, (a, _args, v) => reportArns(a.policyArns, v)),
 93	            validateResourceOfType(aws.iam.GroupPolicyAttachmentsExclusive, (a, _args, v) => reportArns(a.policyArns, v)),
 94	            validateResourceOfType(aws.iam.Role, (r, _args, v) => reportArns(r.managedPolicyArns, v)),
 95	        ],
 96	    },
 97	    {
 98	        name: "aurora-deletion-protection",
 99	        description: "Aurora / RDS clusters must have deletion protection on.",
100	        enforcementLevel: "mandatory",
101	        validateResource: validateResourceOfType(aws.rds.Cluster, (c, _args, v) => {
102	            if (c.deletionProtection !== true) v("Set deletionProtection: true on every prod cluster.");
103	        }),
104	    },
105	    {
106	        name: "s3-public-access-block-all-on",
107	        description: "Every public access block must set all four flags to true.",
108	        enforcementLevel: "mandatory",
109	        validateResource: validateResourceOfType(aws.s3.BucketPublicAccessBlock, (b, _args, v) => {
110	            const flags = {
111	                blockPublicAcls: b.blockPublicAcls,
112	                blockPublicPolicy: b.blockPublicPolicy,
113	                ignorePublicAcls: b.ignorePublicAcls,
114	                restrictPublicBuckets: b.restrictPublicBuckets,
115	            };
116	            const off = Object.entries(flags).filter(([, val]) => val !== true).map(([k]) => k);
117	            if (off.length > 0) v(`Public access block must set ${off.join(", ")} to true.`);
118	        }),
119	    },
120	];
121	// Entry point of the policy pack. Constructing PolicyPack starts the policy analyzer when the
122	// Pulumi CLI runs it (`pulumi up --policy-pack <dir>`); the checks live in policies.ts.
123	import { PolicyPack } from "@pulumi/policy";
124	import { policies } from "./policies";
125	
126	new PolicyPack("example-org-aws-policies", { policies });
127	{
128	  "name": "example-org-aws-policies",
129	  "version": "0.1.0",
130	  "private": true,
131	  "description": "Pulumi Policies pack for prod stacks (framework layer 5, OD8). Phase 2.",
132	  "main": "index.ts",
133	  "scripts": {
134	    "typecheck": "tsc --noEmit",
135	    "test": "tsc && node bin/policies.test.js"
136	  },
137	  "dependencies": {
138	    "@pulumi/aws": "7.51.1",
139	    "@pulumi/policy": "1.21.0",
140	    "@pulumi/pulumi": "3.272.0"
141	  },
142	  "devDependencies": {
143	    "@types/node": "26.6.5",
144	    "typescript": "6.0.3"
145	  }
146	}
147	{
148	  "compilerOptions": {
149	    "strict": true,
150	    "target": "es2022",
151	    "module": "node16",
152	    "moduleResolution": "node16",
153	    "esModuleInterop": true,
154	    "skipLibCheck": true,
155	    "outDir": "bin"
156	  },
157	  "files": [
158	    "index.ts",
159	    "policies.ts",
160	    "policies.test.ts"
161	  ]
162	}
163	description: Mandatory guardrails for prod stacks (framework layer 5; compensates OD8)
164	runtime: nodejs

